import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface BrowserHijackingProps {
  onEscape: () => void;
  onLearnMore: () => void;
}

const BrowserHijacking: React.FC<BrowserHijackingProps> = ({ onEscape, onLearnMore }) => {
  const [isActive, setIsActive] = useState(false);
  const [threatLevel, setThreatLevel] = useState(0);

  // Use real scareware browser hijacking techniques
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true
  });

  useEffect(() => {
    // Start the browser hijacking
    const startHijacking = () => {
      setIsActive(true);
      
      // Escalate threat level over time
      const threatTimer = setInterval(() => {
        setThreatLevel(prev => {
          if (prev < 10) return prev + 1;
          clearInterval(threatTimer);
          return prev;
        });
      }, 2000);
    };

    // Start hijacking after a short delay
    setTimeout(startHijacking, 500);
  }, []);

  const handleEscape = () => {
    onEscape();
  };

  const handleLearnMore = () => {
    onLearnMore();
  };

  if (!isActive) {
    return null;
  }

  return (
    <>
      {/* Real scareware technique: Complete browser takeover */}
      <div 
        className="browser-hijacking-overlay"
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: `linear-gradient(45deg, #ff0000, #8b0000, #ff0000)`,
          zIndex: 10000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          textAlign: 'center',
          animation: 'flash 0.3s infinite alternate'
        }}
      >
        <div style={{ maxWidth: '800px', padding: '2rem' }}>
          <div style={{ fontSize: '5rem', marginBottom: '2rem' }}>💀</div>
          <h1 style={{ 
            fontSize: '4rem', 
            marginBottom: '2rem', 
            textShadow: '3px 3px 6px rgba(0,0,0,0.8)',
            animation: 'shake 0.5s infinite'
          }}>
            SYSTEM COMPROMISED!
          </h1>
          
          <div style={{ fontSize: '2rem', marginBottom: '2rem' }}>
            Threat Level: {threatLevel}/10
          </div>
          
          <div style={{ fontSize: '1.5rem', marginBottom: '2rem' }}>
            Your computer has been completely hijacked!
            <br />
            All data is being transmitted to hackers!
            <br />
            Banking information compromised!
            <br />
            Passwords and personal files stolen!
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '2rem', 
            borderRadius: '12px',
            marginBottom: '2rem',
            border: '3px solid #fff',
            boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <div style={{ fontSize: '1.8rem', marginBottom: '1rem' }}>
              <strong>🚨 IMMEDIATE ACTION REQUIRED 🚨</strong>
            </div>
            <div style={{ fontSize: '1.3rem' }}>
              Call our emergency support: 1-800-FAKE-URGENT
              <br />
              Or pay $199.99 for instant protection
              <br />
              <strong>Time is running out!</strong>
            </div>
          </div>

          <div style={{ 
            background: 'rgba(255, 255, 255, 0.2)', 
            padding: '1.5rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            fontSize: '1rem'
          }}>
            <strong>SIMULATION MODE:</strong> This demonstrates the most aggressive real scareware techniques.
            <br />
            <strong>Blocked escape attempts: {blockedAttempts}</strong>
            <br />
            <strong>Fullscreen mode: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
            <br />
            <strong>Threat level: {threatLevel}/10</strong>
            <br />
            Real browser hijacking would be extremely difficult to escape.
          </div>

          <div style={{ marginTop: '3rem' }}>
            <button 
              className="button button-success" 
              onClick={handleEscape}
              style={{ 
                fontSize: '1.5rem', 
                padding: '1.5rem 3rem', 
                marginRight: '2rem',
                background: '#28a745',
                border: '4px solid #fff',
                boxShadow: '0 8px 16px rgba(0,0,0,0.4)',
                borderRadius: '8px'
              }}
            >
              🚪 Emergency Escape (Simulation)
            </button>
            <button 
              className="button button-primary" 
              onClick={handleLearnMore}
              style={{ 
                fontSize: '1.5rem', 
                padding: '1.5rem 3rem',
                background: '#007bff',
                border: '4px solid #fff',
                boxShadow: '0 8px 16px rgba(0,0,0,0.4)',
                borderRadius: '8px'
              }}
            >
              📚 Learn More
            </button>
          </div>
        </div>
      </div>

      {/* Real scareware technique: Multiple persistent popups */}
      <div 
        style={{
          position: 'fixed',
          top: '50px',
          right: '50px',
          background: 'white',
          border: '4px solid #ff0000',
          borderRadius: '12px',
          padding: '1.5rem',
          zIndex: 20000,
          boxShadow: '0 12px 48px rgba(0,0,0,0.6)',
          animation: 'shake 0.3s infinite'
        }}
      >
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>⚠️</div>
          <div style={{ fontWeight: 'bold', color: '#ff0000', marginBottom: '0.5rem', fontSize: '1.2rem' }}>
            CRITICAL ALERT!
          </div>
          <div style={{ fontSize: '1rem', marginBottom: '1rem' }}>
            System completely compromised!
            <br />
            <strong>SIMULATION MODE</strong>
          </div>
          <button 
            onClick={handleEscape}
            style={{
              background: '#ff0000',
              color: 'white',
              border: 'none',
              padding: '0.8rem 1.5rem',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '1rem',
              fontWeight: 'bold'
            }}
          >
            EMERGENCY FIX
          </button>
        </div>
      </div>

      {/* Second persistent popup */}
      <div 
        style={{
          position: 'fixed',
          bottom: '50px',
          left: '50px',
          background: 'white',
          border: '4px solid #ff0000',
          borderRadius: '12px',
          padding: '1.5rem',
          zIndex: 20000,
          boxShadow: '0 12px 48px rgba(0,0,0,0.6)',
          animation: 'shake 0.4s infinite'
        }}
      >
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>🚨</div>
          <div style={{ fontWeight: 'bold', color: '#ff0000', marginBottom: '0.5rem', fontSize: '1.2rem' }}>
            URGENT WARNING!
          </div>
          <div style={{ fontSize: '1rem', marginBottom: '1rem' }}>
            Data breach in progress!
            <br />
            <strong>SIMULATION MODE</strong>
          </div>
          <button 
            onClick={handleEscape}
            style={{
              background: '#ff0000',
              color: 'white',
              border: 'none',
              padding: '0.8rem 1.5rem',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '1rem',
              fontWeight: 'bold'
            }}
          >
            STOP ATTACK
          </button>
        </div>
      </div>
    </>
  );
};

export default BrowserHijacking;
